// Validate the radar request and build one fetch item per board.
// Output: [{ error }] on bad input, else [{ ats, token, url }, ...].
const ATS_URLS = {
  greenhouse: (base, t) => `${base ?? 'https://boards-api.greenhouse.io'}/v1/boards/${t}/jobs`,
  lever: (base, t) => `${base ?? 'https://api.lever.co'}/v0/postings/${t}?mode=json`,
  ashby: (base, t) => `${base ?? 'https://api.ashbyhq.com'}/posting-api/job-board/${t}`,
};
const TOKEN = /^[A-Za-z0-9_-]{1,100}$/;
// Tests only: the docker compose fixture server. A strict pattern instead of new URL()
// (not usable in n8n's Code-node sandbox); nothing but scheme, host and optional port.
const FIXTURE_BASE = /^http:\/\/job-fixtures(:\d{1,5})?\/?$/;
const fail = (error) => [{ json: { error } }];

const raw = $input.first().json.body;
const { boards, profile, limit, apiBase } = raw && typeof raw === 'object' ? raw : {};

if (!Array.isArray(boards) || boards.length === 0 || boards.length > 50)
  return fail('boards must be a non-empty array of at most 50');
for (const b of boards) {
  if (!Object.prototype.hasOwnProperty.call(ATS_URLS, b?.ats)) return fail(`unsupported ats: ${b?.ats}`);
  if (typeof b.token !== 'string' || !TOKEN.test(b.token)) return fail(`invalid token: ${b.token}`);
}
const keywords = profile?.titleKeywords;
if (!Array.isArray(keywords) || !keywords.some((k) => typeof k === 'string' && k.trim()))
  return fail('profile.titleKeywords is required');
if (limit !== undefined && !(Number.isInteger(limit) && limit >= 1 && limit <= 50))
  return fail('limit must be an integer from 1 to 50');

let base;
if (apiBase !== undefined) {
  if (typeof apiBase !== 'string' || !FIXTURE_BASE.test(apiBase)) return fail('apiBase is not allowed');
  base = apiBase.replace(/\/$/, '');
}

return boards.map((b) => ({ json: { ats: b.ats, token: b.token, url: ATS_URLS[b.ats](base, b.token) } }));

// Normalize every board's jobs, filter and score them against the profile, dedup,
// order and limit. Input: one HTTP full response per board, in board order.
// Output: [{ count, jobs, errors }].
const body = $('Webhook').first().json.body;
const boards = $('Validate Request').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);

const clean = (list) =>
  (Array.isArray(list) ? list : []).filter((k) => typeof k === 'string' && k.trim()).map((k) => k.trim());
const titleKeywords = clean(body.profile.titleKeywords);
const excludeKeywords = clean(body.profile.excludeTitleKeywords);
const locationKeywords = clean(body.profile.locations);
const limit = body.limit ?? 10;

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const iso = (v) => {
  const d = new Date(v);
  return v == null || Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const has = (text, k) => text.toLowerCase().includes(k.toLowerCase());

const NORMALIZE = {
  greenhouse: (data, token) => (Array.isArray(data?.jobs) ? data.jobs : []).map((j) => ({
    company: str(j.company_name) || token,
    title: str(j.title),
    location: str(j.location?.name),
    url: j.absolute_url,
    postedAt: iso(j.first_published ?? j.updated_at),
    remote: false,
  })),
  lever: (data, token) => (Array.isArray(data) ? data : []).map((j) => {
    const all = Array.isArray(j.categories?.allLocations) ? j.categories.allLocations.map(str).filter(Boolean) : [];
    return {
      company: token,
      title: str(j.text),
      location: all.length ? all.join(' / ') : str(j.categories?.location),
      url: j.hostedUrl,
      postedAt: iso(j.createdAt),
      remote: j.workplaceType === 'remote',
    };
  }),
  ashby: (data, token) => (Array.isArray(data?.jobs) ? data.jobs : [])
    .filter((j) => j.isListed !== false)
    .map((j) => ({
      company: token,
      title: str(j.title),
      location: [j.location, ...(Array.isArray(j.secondaryLocations) ? j.secondaryLocations : []).map((l) => l?.location)]
        .map(str).filter(Boolean).join(' / '),
      url: j.jobUrl,
      postedAt: iso(j.publishedAt),
      remote: j.isRemote === true,
    })),
};

const errors = [];
const newest = new Map();
boards.forEach((board, i) => {
  const r = responses[i] ?? {};
  const status = typeof r.statusCode === 'number' ? r.statusCode : 0;
  if (status < 200 || status > 299) {
    errors.push({ source: board.ats, board: board.token, status });
    return;
  }
  for (const job of NORMALIZE[board.ats](r.body, board.token)) {
    const key = `${job.company}|${job.title}|${job.location}`.toLowerCase();
    const seen = newest.get(key);
    if (!seen || (job.postedAt ?? '') > (seen.job.postedAt ?? '')) newest.set(key, { board, job });
  }
});

const jobs = [];
for (const { board, job } of newest.values()) {
  if (excludeKeywords.some((k) => has(job.title, k))) continue;
  const titleHits = titleKeywords.filter((k) => has(job.title, k));
  if (titleHits.length === 0) continue;
  const remote = job.remote || /remote/i.test(job.location);
  const locationHits = locationKeywords.filter(
    (k) => has(job.location, k) || (k.toLowerCase() === 'remote' && remote),
  );
  if (locationKeywords.length > 0 && locationHits.length === 0) continue;
  jobs.push({
    source: board.ats,
    board: board.token,
    company: job.company,
    title: job.title,
    location: job.location,
    url: job.url,
    postedAt: job.postedAt,
    score: 10 * titleHits.length + (locationHits.length > 0 ? 5 : 0),
    matched: [...titleHits, ...locationHits],
  });
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
jobs.sort((a, b) =>
  b.score - a.score || cmp(b.postedAt ?? '', a.postedAt ?? '') || cmp(a.title, b.title));
const top = jobs.slice(0, limit);
return [{ json: { count: top.length, jobs: top, errors } }];
